package com.tambapps.pokemon.alakastats.infrastructure.repository

import alakastats.composeapp.generated.resources.Res
import com.tambapps.pokemon.MoveName
import com.tambapps.pokemon.PokemonName
import com.tambapps.pokemon.PokemonNormalizer
import com.tambapps.pokemon.alakastats.domain.model.Pokedex
import com.tambapps.pokemon.champions.data.ChampionsDex
import kotlinx.coroutines.test.runTest
import kotlinx.serialization.json.Json
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * The bundled Pokédex (generated by data-scripts/generate_pokedex.js) is complete and consistent, and agrees with the
 * other Champions data of the app. A failure lists every problem, for the generator or its sources to be fixed
 */
class PokedexFileTest {

    private val json = Json { ignoreUnknownKeys = true }

    private suspend fun entity() = json.decodeFromString<PokedexEntity>(Res.readBytes(POKEDEX_FILE).decodeToString())

    private suspend fun pokedex(): Pokedex = entity().toDomain()

    @Test
    fun itIsTheCurrentRegulation() = runTest {
        val meta = entity().meta
        assertEquals(POKEDEX_SCHEMA_VERSION, meta.schemaVersion)
        assertEquals("gen9championsvgc2026regmc", meta.formatId)
    }

    @Test
    fun everyEntryHasItsNames() = runTest {
        val pokedex = pokedex()
        val entries = pokedex.species + pokedex.moves + pokedex.abilities + pokedex.items + pokedex.types
        val problems = entries.filter { it.name.en.isBlank() || it.name.fr.isBlank() }.map { "${it.id}: ${it.name}" }
        assertEquals(emptyList(), problems)
        assertEquals(18, pokedex.types.size)
    }

    /** The ids are the names of the app, normalized like the app normalizes the names it gets */
    @Test
    fun theIdsAreTheNormalizedNames() = runTest {
        val pokedex = pokedex()
        val entries = pokedex.species + pokedex.moves + pokedex.abilities + pokedex.items
        val problems = entries.filter { it.id != PokemonNormalizer.normalize(it.name.en) }.map { "${it.id}: ${it.name.en}" }
        assertEquals(emptyList(), problems)
        assertEquals("charizard-mega-y", pokedex.species(PokemonName("Charizard-Mega-Y"))?.id)
        assertEquals("trick-room", pokedex.move(MoveName("Trick Room"))?.id)
    }

    @Test
    fun everyPokemonCanBePlayed() = runTest {
        val problems = pokedex().species.flatMap { s ->
            listOfNotNull(
                "${s.id} has no ability".takeIf { s.abilities.isEmpty() },
                "${s.id} learns no move".takeIf { s.moves.isEmpty() },
                "${s.id} has no type".takeIf { s.types.isEmpty() },
            )
        }
        assertEquals(emptyList(), problems)
    }

    @Test
    fun aMegaLearnsTheMovesOfItsBaseForm() = runTest {
        val pokedex = pokedex()
        val megas = pokedex.species.filter { it.isMega }
        assertTrue(megas.size > 50)
        val problems = megas.mapNotNull { mega ->
            val base = mega.megaOf?.let(pokedex::species) ?: return@mapNotNull "${mega.id} has no base form"
            when {
                mega.moves != base.moves -> "${mega.id} doesn't learn the moves of ${base.id}"
                mega.megaStone == null -> "${mega.id} has no Mega Stone"
                mega.pokemonName.normalized !in mega.megaStone.megaForms -> "${mega.megaStone.id} doesn't make ${mega.id} mega evolve"
                mega !in pokedex.formsOf(base) -> "${mega.id} isn't a form of ${base.id}"
                else -> null
            }
        }
        assertEquals(emptyList(), problems)
    }

    /** The damage calc's data comes from another source (the Nerd of Now calculator): both must agree */
    @Test
    fun itAgreesWithTheDamageCalc() = runTest {
        val pokedex = pokedex()
        var compared = 0
        val problems = pokedex.species.mapNotNull { s ->
            val calcSpecies = ChampionsDex.speciesOrNull(s.pokemonName) ?: return@mapNotNull null
            compared++
            when {
                calcSpecies.baseStats != s.baseStats -> "${s.id}: base stats ${s.baseStats} vs ${calcSpecies.baseStats}"
                setOfNotNull(calcSpecies.primaryType, calcSpecies.secondaryType) != s.types.toSet() ->
                    "${s.id}: types ${s.types} vs ${calcSpecies.primaryType}/${calcSpecies.secondaryType}"
                else -> null
            }
        }
        assertEquals(emptyList(), problems)
        assertTrue(compared > 200, "only $compared Pokémon compared")
        val unknownMoves = ChampionsDex.allMoves.map { it.name }.filter { pokedex.move(it) == null }
        assertEquals(emptyList(), unknownMoves)
    }

    /** The damage calc's preset sets only use moves their Pokémon learn */
    @Test
    fun thePresetSetsAreLegal() = runTest {
        val pokedex = pokedex()
        val sets = json.decodeFromString<PresetSetsEntity>(Res.readBytes(PRESET_SETS_FILE).decodeToString()).toDomain()
        val problems = mutableListOf<String>()
        for (set in sets.species.flatMap { sets.of(it) }) {
            val where = "${set.species.value} (${set.name})"
            val species = pokedex.species(set.species)
            if (species == null) {
                problems += "$where: not in the Pokédex"
                continue
            }
            for (move in set.moves) {
                val pokedexMove = pokedex.move(move)
                if (pokedexMove == null) problems += "$where: unknown move ${move.value}"
                else if (pokedexMove !in species.moves) problems += "$where: doesn't learn ${move.value}"
            }
        }
        assertEquals(emptyList(), problems)
    }

    @Test
    fun aCosmeticFormIsItsBaseForm() = runTest {
        val pokedex = pokedex()
        assertEquals("vivillon", pokedex.species(PokemonName("Vivillon-Polar"))?.id)
        assertEquals("Prismillon", pokedex.species(PokemonName("vivillon"))?.name?.fr)
    }
}
